from pathlib import Path
import argparse, hashlib, json, time, importlib.metadata as md
import numpy as np
from PIL import Image, ImageDraw
import torch
from transformers import AutoImageProcessor, AutoModelForDepthEstimation
ap=argparse.ArgumentParser();ap.add_argument('--source',required=True);ap.add_argument('--metadata',required=True);ap.add_argument('--out',required=True);a=ap.parse_args()
p=Path(__file__).resolve().parent;s=Path(a.source);o=Path(a.out);o.mkdir(parents=True,exist_ok=True);sha=lambda f:hashlib.sha256(Path(f).read_bytes()).hexdigest();meta=json.loads(Path(a.metadata).read_text());assert sha(s)==meta['sha256'];im=Image.open(s).convert('RGB');artifact=json.loads((p/'provenance/model-manifest.json').read_text())
for f in artifact['artifacts']:assert sha(p/'model'/f['path'])==f['sha256']
torch.set_num_threads(1);torch.set_num_interop_threads(1)
proc=AutoImageProcessor.from_pretrained(p/'model',local_files_only=True,trust_remote_code=False,use_fast=False);model=AutoModelForDepthEstimation.from_pretrained(p/'model',local_files_only=True,trust_remote_code=False,use_safetensors=True).eval();x=proc(images=im,return_tensors='pt');t=time.time()
with torch.inference_mode():raw=model(**x).predicted_depth[0].cpu().numpy().astype('float32')
elapsed=time.time()-t;finite=np.isfinite(raw);lo=float(raw[finite].min());hi=float(raw[finite].max());assert hi>lo;np.save(o/'relative-inverse-depth-model-grid.npy',raw,allow_pickle=False);Image.fromarray(np.where(finite,np.clip((raw-lo)/(hi-lo),0,1)*65535,0).round().astype('uint16')).save(o/'relative-inverse-depth-gray16-model-grid.png')
res=torch.nn.functional.interpolate(torch.from_numpy(raw)[None,None],size=(im.height,im.width),mode='bicubic',align_corners=False)[0,0].numpy();np.save(o/'relative-inverse-depth-resampled-source-grid.npy',res,allow_pickle=False);Image.fromarray((np.clip((res-lo)/(hi-lo),0,1)*255).round().astype('uint8')).save(o/'relative-inverse-depth-gray8-resampled-source-grid.png')
mask=Image.new('L',im.size);d=ImageDraw.Draw(mask)
for r in meta.get('exclusions',[]):
 if r['shape']=='rectangle':d.rectangle(r['points'],fill=r['class'])
 elif r['shape']=='polygon':d.polygon([tuple(pt) for pt in r['points']],fill=r['class'])
mask.save(o/'manual-exclusion-classes-source-grid.png');Image.new('L',im.size,255).save(o/'confidence-unknown-source-grid.png');Image.fromarray((~finite).astype('uint8')*255).save(o/'nonfinite-invalid-model-grid.png');dark=np.asarray(im).max(axis=2)<=meta.get('dark_rgb_max_threshold',25);Image.fromarray(dark.astype('uint8')*255).save(o/'dark-low-signal-caution-source-grid.png')
r={'source':{**meta,'path':str(s),'bytes':s.stat().st_size,'sha256':sha(s),'size':list(im.size),'crop':[0,0,im.width,im.height]},'method':{'repo':artifact['repo'],'revision':artifact['revision'],'weights_sha256':sha(p/'model/model.safetensors'),'device':'cpu','dtype':'float32','threads':1,'trust_remote_code':False,'local_files_only':True,'weights_format':'safetensors','versions':{k:md.version(k) for k in ['torch','transformers','safetensors','pillow','numpy']},'input_tensor_shape':list(x['pixel_values'].shape),'raw_shape':list(raw.shape),'processor_config':json.loads((p/'model/preprocessor_config.json').read_text()),'forward_seconds':elapsed},'range':{'min':lo,'max':hi,'nonfinite_count':int((~finite).sum())},'value_definition':'Relative inverse-depth-like prediction: larger/white generally nearer, smaller/black generally farther. Not metric distance or ordinary image luminance. Per-image normalized numbers cannot be compared as distance across images.','normalization':'(raw-min)/(max-min); source-grid output is explicitly derived bicubic interpolation align_corners=False, not native-resolution independent prediction.','masks':{'manual_exclusions':'Conservative incomplete manually inspected ROIs, later drawn classes overwrite overlap, 0 unlabelled NOT certified valid.','confidence_unknown':'255 everywhere means NO calibrated confidence, NEVER high confidence.','nonfinite':'255 nonfinite numerical output; 0 merely finite, NOT geometry validity.','dark_low_signal':'255 where all original RGB channels <= threshold (default25), heuristic low-signal caution only; this brightness mask is NOT the depth algorithm.','occluded_hidden':'Unobserved hidden surfaces cannot be inferred as fact.'},'dark_low_signal_fraction':float(dark.mean()),'limitations':['Single monocular depth is not metric geometry, scale, contact or camera calibration','Stylized CG, character motion, reflections, transparency, shadows and light can invalidate predictions','No replacement for native multiview references and direct unwarped overlays']}
r['outputs']=[{'path':f.name,'bytes':f.stat().st_size,'sha256':sha(f)} for f in sorted(o.iterdir()) if f.is_file() and f.name!='report.json'];(o/'report.json').write_text(json.dumps(r,ensure_ascii=False,indent=2));print(json.dumps({'raw_shape':raw.shape,'range':r['range'],'forward_seconds':elapsed,'dark_fraction':r['dark_low_signal_fraction']}))
